            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    t = 1
    for exponent in factors.values():
        t *= (exponent + 1)
    return t

def nu_2(x):
    if x == 0:
        return float('inf')
    count = 0
    while x > 0 and x % 2 == 0:
        count += 1
        x //= 2
    return count

def is_exotic(n):
    """Checks if n is exotic, i.e., nu_2(tau(n)) = 1."""
    t = tau(n)
    return nu_2(t) == 1

